  const cap=h.cylinder(.18,.07,2.04,1.2,z,h.steel,drive,32);cap.rotation.z=Math.PI/2;
  h.box(.27,.11,.18,1.76,1.405,z,h.steel,drive);
  h.box(1.1,.07,.57,1.58,.95,z,h.edge,drive);
  for(const dz of [-.21,.21])h.barBetween([1.11,.6,z+dz],[2.05,.95,z+dz],.026,h.steel,drive);
